insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São objetivos do Plano Nacional de Políticas sobre Drogas, dentre outros, promover a interdisciplinaridade e a integração dos programas nas áreas de saúde, educação, trabalho, assistência social, previdência social, habitação, cultura, desporto e lazer; viabilizar a ampla participação social; priorizar programas articulados com estabelecimentos de ensino, sociedade e família; ampliar as alternativas de inserção social e econômica do usuário ou dependente, priorizando escolarização e qualificação profissional; e promover o acesso do usuário ou dependente a todos os serviços públicos.', '["Interdisciplinaridade e integração de programas.","Ampla participação social.","Articulação com escolas, sociedade e família.","Inserção social e econômica do usuário.","Acesso a todos os serviços públicos."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.840, de 2019 (Capítulo II-A)."]'::jsonb, 'O plano prioriza ações nas escolas para prevenir o uso de drogas.', '["Assertiva que restringe o Plano Nacional à área da saúde erra: abrange várias áreas."]'::jsonb, '[]'::jsonb, '["Art. 8º-A","Art. 8º-E"]'::jsonb, 'under_review', 'claude'
