insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os conselhos de políticas sobre drogas, constituídos por Estados, Distrito Federal e Municípios, terão os objetivos de auxiliar na elaboração de políticas sobre drogas; colaborar com os órgãos governamentais no planejamento e na execução das políticas; propor a celebração de instrumentos de cooperação para programas de prevenção, tratamento, acolhimento, reinserção e repressão ao tráfico; promover estudos; propor políticas que permitam a integração do usuário ou dependente no processo social, econômico, político e cultural; e desenvolver outras atividades relacionadas.', '["Auxiliar na elaboração das políticas.","Colaborar no planejamento e na execução.","Propor instrumentos de cooperação.","Promover estudos.","Propor a integração do usuário no processo social."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.840, de 2019."]'::jsonb, 'O conselho municipal propõe convênio para um programa de reinserção no trabalho.', '["Assertiva que atribui aos conselhos estaduais e municipais o poder de legislar sobre drogas erra: eles auxiliam e propõem."]'::jsonb, '[]'::jsonb, '["Art. 8º-D"]'::jsonb, 'under_review', 'claude'
