insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As atividades de prevenção do uso indevido de drogas devem observar princípios e diretrizes como o reconhecimento do uso indevido como fator de interferência na qualidade de vida; a adoção de conceitos objetivos e de fundamentação científica; o fortalecimento da autonomia e da responsabilidade individual; o compartilhamento de responsabilidades com o setor privado e a sociedade; estratégias diferenciadas conforme as populações e as drogas; o reconhecimento do ''não-uso'', do ''retardamento do uso'' e da redução de riscos como resultados desejáveis; e o tratamento especial às parcelas mais vulneráveis da população.', '["Fundamentação científica e conceitos objetivos.","Autonomia e responsabilidade individual.","Estratégias diferenciadas para cada população e droga.","Resultados desejáveis: não-uso, retardamento do uso e redução de riscos."]'::jsonb, '["A lei reconhece a redução de riscos como resultado desejável."]'::jsonb, 'Campanha adaptada à realidade de jovens de uma região aplica estratégia diferenciada.', '["Assertiva que considera apenas a abstinência total como resultado desejável da prevenção erra."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
