insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As instituições da sociedade civil, sem fins lucrativos, com atuação nas áreas da atenção à saúde e da assistência social, que atendam usuários ou dependentes de drogas poderão receber recursos do Funad, condicionados à sua disponibilidade orçamentária e financeira.', '["Entidades sem fins lucrativos podem receber recursos do Funad.","Condicionados à disponibilidade orçamentária e financeira."]'::jsonb, '["Funad: Fundo Nacional Antidrogas."]'::jsonb, 'Entidade filantrópica de acolhimento recebe recursos do Funad, se houver disponibilidade.', '["Assertiva que garante recursos do Funad independentemente de disponibilidade orçamentária erra."]'::jsonb, '[{"termo":"Funad","significado":"Fundo Nacional Antidrogas."}]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-25'
