insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O usuário e o dependente de drogas que, em razão da prática de infração penal, estiverem cumprindo pena privativa de liberdade ou submetidos a medida de segurança, têm garantidos os serviços de atenção à sua saúde, definidos pelo respectivo sistema penitenciário.', '["Preso usuário ou dependente tem garantidos serviços de atenção à saúde.","Serviços definidos pelo sistema penitenciário."]'::jsonb, '["Vale para pena privativa de liberdade e medida de segurança."]'::jsonb, 'O preso dependente recebe atendimento de saúde no próprio sistema penitenciário.', '["Assertiva que exclui o preso do direito à atenção à saúde por drogas erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
