insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As plantações ilícitas serão imediatamente destruídas pelo delegado de polícia na forma do art. 50-A, que recolherá quantidade suficiente para exame pericial, de tudo lavrando auto de levantamento das condições encontradas, com a delimitação do local, asseguradas as medidas necessárias para a preservação da prova. Em caso de queimada, observar-se-á o Decreto nº 2.661, de 1998, dispensada a autorização prévia do Sisnama. As glebas cultivadas com plantações ilícitas serão expropriadas, conforme o art. 243 da Constituição.', '["Destruição imediata pelo delegado de polícia.","Recolhe amostra para perícia e lavra auto de levantamento.","Queimada: cautelas ambientais, sem autorização prévia do Sisnama.","Glebas expropriadas (art. 243 da Constituição)."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 12.961, de 2014 (destruição pelo delegado).","Os §§ 1º e 2º foram revogados."]'::jsonb, 'O delegado destrói a plantação de maconha após coletar amostra e lavrar o auto.', '["Assertiva que exige autorização judicial prévia para destruir a plantação ilícita erra, segundo a redação dada pela Lei nº 12.961, de 2014."]'::jsonb, '[]'::jsonb, '["Art. 50-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-32'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tráfico de drogas: importar, exportar, remeter, preparar, produzir, fabricar, adquirir, vender, expor à venda, oferecer, ter em depósito, transportar, trazer consigo, guardar, prescrever, ministrar, entregar a consumo ou fornecer drogas, ainda que gratuitamente, sem autorização ou em desacordo com determinação legal ou regulamentar. Pena: reclusão de 5 a 15 anos e 500 a 1.500 dias-multa. Nas mesmas penas incorre quem pratica condutas relativas a matéria-prima, insumo ou produto químico destinado à preparação de drogas; quem semeia, cultiva ou colhe plantas que sejam matéria-prima; e quem utiliza local ou bem de que tem a posse ou guarda, ou consente que outrem o utilize, para o tráfico. Há ainda figuras do §1º, IV (venda a policial disfarçado), do §2º (induzir, instigar ou auxiliar ao uso: detenção de 1 a 3 anos), do §3º (oferecer droga eventualmente, sem lucro, a pessoa de relacionamento, para consumirem juntos: detenção de 6 meses a 1 ano) e o tráfico privilegiado do §4º.', '["Tipo misto alternativo com 18 núcleos.","Pena: reclusão de 5 a 15 anos e 500 a 1.500 dias-multa.","§1º: matéria-prima, insumos, plantio e cessão de local.","§2º: induzir, instigar ou auxiliar o uso.","§3º: oferecer droga eventualmente, sem lucro, a pessoa de relacionamento.","§4º: tráfico privilegiado (redução de pena para o primário, de bons antecedentes, que não se dedique ao crime nem integre organização)."]'::jsonb, '["Crime de ação múltipla: praticar mais de um núcleo no mesmo contexto é crime único.","O tráfico privilegiado (§4º) NÃO é equiparado a hediondo (STF).","Equiparado a hediondo na forma do caput e do §1º."]'::jsonb, 'Quem guarda drogas em casa para entregar a terceiros pratica tráfico, ainda que sem lucro.', '["Assertiva que considera hediondo o tráfico privilegiado do §4º erra, conforme o STF."]'::jsonb, '[{"termo":"Tráfico privilegiado","significado":"Causa de diminuição de pena para o réu primário, de bons antecedentes, que não integra organização criminosa."}]'::jsonb, '["Art. 28","Art. 40","Art. 44"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-33'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fabricar, adquirir, utilizar, transportar, oferecer, vender, distribuir, entregar a qualquer título, possuir, guardar ou fornecer, ainda que gratuitamente, maquinário, aparelho, instrumento ou qualquer objeto destinado à fabricação, preparação, produção ou transformação de drogas, sem autorização ou em desacordo com determinação legal ou regulamentar. Pena: reclusão de 3 a 10 anos e 1.200 a 2.000 dias-multa.', '["Crime de petrechos para o tráfico.","Objeto destinado à fabricação, preparação, produção ou transformação de drogas.","Reclusão de 3 a 10 anos e 1.200 a 2.000 dias-multa."]'::jsonb, '["O objeto deve ser DESTINADO à produção de drogas."]'::jsonb, 'Quem guarda uma prensa destinada à produção de drogas comete o crime do art. 34.', '["Assertiva que aplica o art. 34 a qualquer objeto, ainda que sem destinação ao preparo de drogas, erra."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-34'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Associação para o tráfico: associarem-se duas ou mais pessoas para o fim de praticar, reiteradamente ou não, qualquer dos crimes previstos nos arts. 33, caput e §1º, e 34. Pena: reclusão de 3 a 10 anos e 700 a 1.200 dias-multa. Nas mesmas penas incorre quem se associa para a prática reiterada do crime de financiamento do tráfico (art. 36).', '["Associação de 2 ou mais pessoas.","Fim de praticar, reiteradamente ou não, os crimes dos arts. 33 e 34.","Reclusão de 3 a 10 anos e 700 a 1.200 dias-multa.","Parágrafo único: associação para a prática reiterada do financiamento (art. 36)."]'::jsonb, '["Basta a associação de DUAS pessoas (diferente da associação criminosa do CP, que exige 3).","Exige estabilidade e permanência da associação."]'::jsonb, 'Duas pessoas se unem de forma estável para traficar: associação para o tráfico.', '["Assertiva que exige 3 ou mais pessoas para o art. 35 erra: bastam duas."]'::jsonb, '[]'::jsonb, '["Art. 36","Associação criminosa (Código Penal)"]'::jsonb, 'under_review', 'claude'
