insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prescrever ou ministrar, culposamente, drogas, sem que delas necessite o paciente, ou fazê-lo em doses excessivas ou em desacordo com determinação legal ou regulamentar. Pena: detenção de 6 meses a 2 anos e 50 a 200 dias-multa. O juiz comunicará a condenação ao Conselho Federal da categoria profissional a que pertença o agente.', '["Prescrever ou ministrar CULPOSAMENTE drogas.","Detenção de 6 meses a 2 anos e 50 a 200 dias-multa.","Condenação comunicada ao Conselho Federal da categoria profissional."]'::jsonb, '["Único crime CULPOSO da Lei de Drogas.","Pena de DETENÇÃO."]'::jsonb, 'Médico prescreve dose excessiva de substância controlada por imprudência.', '["Assertiva que torna dolosa a conduta do art. 38 erra: o crime é culposo."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-38'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Conduzir embarcação ou aeronave após o consumo de drogas, expondo a dano potencial a incolumidade de outrem. Pena: detenção de 6 meses a 3 anos, além da apreensão do veículo, cassação da habilitação ou proibição de obtê-la, pelo mesmo prazo da pena privativa de liberdade, e 200 a 400 dias-multa. Se o veículo for de transporte coletivo de passageiros, as penas de prisão e multa serão de 4 a 6 anos e de 400 a 600 dias-multa.', '["Conduzir embarcação ou aeronave após consumir drogas.","Exige exposição de outrem a dano potencial (perigo concreto).","Detenção de 6 meses a 3 anos, apreensão do veículo e cassação da habilitação.","Transporte coletivo: 4 a 6 anos."]'::jsonb, '["Aplica-se a embarcação e aeronave; para veículos terrestres vale o Código de Trânsito."]'::jsonb, 'Piloto conduz aeronave após consumir droga, expondo passageiros a perigo.', '["Assertiva que aplica o art. 39 à condução de automóvel erra: trata de embarcação e aeronave."]'::jsonb, '[]'::jsonb, '["Código de Trânsito Brasileiro"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-39'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas previstas nos arts. 33 a 37 são aumentadas de um sexto a dois terços se a natureza, a procedência da substância e as circunstâncias evidenciarem a transnacionalidade do delito; se o agente praticar o crime prevalecendo-se de função pública ou no desempenho de missão de educação, poder familiar, guarda ou vigilância; se a infração for cometida nas dependências ou imediações de estabelecimentos prisionais, de ensino, hospitalares, de entidades estudantis, sociais, culturais, recreativas, esportivas ou beneficentes, de locais de trabalho coletivo, de recintos de espetáculos, de serviços de tratamento, de unidades militares ou policiais ou em transportes públicos; se o crime for praticado com violência, grave ameaça, emprego de arma de fogo ou intimidação difusa ou coletiva; se caracterizado o tráfico interestadual; se envolver ou visar a atingir criança ou adolescente ou quem tenha diminuída a capacidade de entendimento; e se o agente financiar ou custear o crime, entre outras hipóteses.', '["Aumento de 1/6 a 2/3 para os arts. 33 a 37.","I: transnacionalidade.","II: função pública ou missão de educação, poder familiar, guarda ou vigilância.","III: proximidade de escolas, hospitais, presídios, transporte público etc.","IV: violência, grave ameaça, arma de fogo.","V: tráfico interestadual.","VI: criança, adolescente ou pessoa com capacidade diminuída.","VII: financiamento ou custeio."]'::jsonb, '["Não se aplica ao art. 38 nem ao art. 39.","Súmula do STJ: para o tráfico interestadual basta a destinação a outro Estado, sem exigir a transposição efetiva da divisa."]'::jsonb, 'Venda de droga na porta de uma escola atrai o aumento do art. 40, III.', '["Assertiva que aplica as causas de aumento do art. 40 ao porte para consumo pessoal erra: elas valem para os arts. 33 a 37."]'::jsonb, '[]'::jsonb, '["Art. 33","Art. 40-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-40'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas previstas nos arts. 33 a 37 serão aplicadas em dobro se o crime tiver sido praticado por integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada, no contexto da atuação ou para a consecução das condutas previstas no art. 2º da lei que institui o marco legal do combate ao crime organizado no Brasil. Aplica-se a pena do concurso material do art. 69 do Código Penal se o crime tiver sido praticado com o emprego de arma de fogo, independentemente de o seu uso estar diretamente ligado ao comércio ilícito de entorpecentes ou de o artefato ter sido utilizado para assegurar o sucesso da mercancia.', '["Penas dos arts. 33 a 37 em DOBRO para integrante de organização criminosa ultraviolenta, grupo paramilitar ou milícia privada.","Emprego de arma de fogo: concurso material (art. 69 do CP).","Independe de o uso da arma estar ligado ao comércio da droga."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei nº 15.358, de 2026.","Aplicação das penas em DOBRO, e não em fração."]'::jsonb, 'Miliciano que trafica drogas tem as penas dobradas.', '["Assertiva que fixa o aumento do art. 40-A em um sexto a dois terços erra: as penas são aplicadas em dobro."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-40-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O indiciado ou acusado que colaborar voluntariamente com a investigação policial e o processo criminal na identificação dos demais coautores ou partícipes do crime e na recuperação total ou parcial do produto do crime, no caso de condenação, terá pena reduzida de um terço a dois terços.', '["Colaboração voluntária na identificação de coautores ou partícipes.","Ou na recuperação do produto do crime.","Redução de 1/3 a 2/3 da pena, em caso de condenação."]'::jsonb, '["A colaboração deve ser VOLUNTÁRIA e eficaz."]'::jsonb, 'O acusado aponta os demais integrantes do grupo e ajuda a recuperar a droga: a pena é reduzida.', '["Assertiva que torna a delação premiada do art. 41 obrigatória para o juiz reduzir a pena erra: exige colaboração voluntária e eficaz."]'::jsonb, '[]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-41'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, na fixação das penas, considerará, com preponderância sobre o previsto no art. 59 do Código Penal, a natureza e a quantidade da substância ou do produto, a personalidade e a conduta social do agente.', '["Natureza e quantidade da substância.","Personalidade e conduta social do agente.","Preponderam sobre o art. 59 do CP."]'::jsonb, '["Critérios com PREPONDERÂNCIA sobre o art. 59 do Código Penal."]'::jsonb, 'A grande quantidade de crack apreendida pesa na fixação da pena-base.', '["Assertiva que dá ao art. 59 do CP preponderância sobre o art. 42 da Lei de Drogas erra."]'::jsonb, '[]'::jsonb, '["Art. 59 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-42'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na fixação da multa a que se referem os arts. 33 a 39, o juiz, atendendo ao que dispõe o art. 42, determinará o número de dias-multa, atribuindo a cada um, segundo as condições econômicas dos acusados, valor não inferior a um trinta avos nem superior a 5 vezes o maior salário mínimo. As multas, que em caso de concurso de crimes serão impostas sempre cumulativamente, podem ser aumentadas até o décuplo se, em virtude da situação econômica do acusado, considerá-las o juiz ineficazes, ainda que aplicadas no máximo.', '["Dia-multa: de um trinta avos a 5 vezes o maior salário mínimo.","Concurso de crimes: multas sempre cumuladas.","Podem ser aumentadas até o décuplo se ineficazes."]'::jsonb, '["Aumento até o DÉCUPLO."]'::jsonb, 'Réu muito rico tem a multa aumentada até o décuplo por ser considerada ineficaz.', '["Assertiva que limita o dia-multa a 3 vezes o maior salário mínimo, no art. 43, erra: é de até 5 vezes."]'::jsonb, '[]'::jsonb, '["Art. 42"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-43'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes previstos nos arts. 33, caput e §1º, e 34 a 37 são inafiançáveis e insuscetíveis de sursis, graça, indulto, anistia e liberdade provisória, vedada a conversão de suas penas em restritivas de direitos. Nos crimes previstos no caput, dar-se-á o livramento condicional após o cumprimento de dois terços da pena, vedada sua concessão ao reincidente específico.', '["Inafiançáveis e insuscetíveis de sursis, graça, indulto, anistia e liberdade provisória.","Vedada a conversão em penas restritivas de direitos.","Livramento condicional após 2/3 da pena, vedado ao reincidente específico."]'::jsonb, '["O STF declarou inconstitucionais a vedação de liberdade provisória e a de conversão em restritivas de direitos (a conversão é possível no tráfico privilegiado).","Livramento: 2/3, e não a fração do Código Penal."]'::jsonb, 'Condenado por tráfico só pode pedir livramento condicional após cumprir dois terços da pena, se não for reincidente específico.', '["Assertiva que fixa o livramento condicional do tráfico em metade da pena erra: são dois terços."]'::jsonb, '[{"termo":"Reincidente específico","significado":"Quem reincide em crime da mesma natureza."}]'::jsonb, '["Art. 33","Lei dos Crimes Hediondos"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-44'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É isento de pena o agente que, em razão da dependência, ou sob o efeito, proveniente de caso fortuito ou força maior, de droga, era, ao tempo da ação ou da omissão, qualquer que tenha sido a infração penal praticada, inteiramente incapaz de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento. Quando absolver o agente, reconhecendo, por força pericial, essas condições, o juiz poderá determinar, na sentença, o seu encaminhamento para tratamento médico adequado.', '["Isenção de pena por dependência ou efeito de droga (caso fortuito ou força maior).","Exige incapacidade TOTAL de entender o ilícito ou de se determinar.","Absolvido: possível encaminhamento a tratamento médico."]'::jsonb, '["Aplica-se a QUALQUER infração penal, e não só aos crimes da Lei de Drogas.","Exige reconhecimento por perícia."]'::jsonb, 'Dependente químico totalmente incapaz de entender o caráter ilícito do furto praticado é isento de pena.', '["Assertiva que limita o art. 45 aos crimes da Lei de Drogas erra: vale para qualquer infração penal."]'::jsonb, '[]'::jsonb, '["Art. 46","Art. 26 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-45'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As penas podem ser reduzidas de um terço a dois terços se, por força das circunstâncias previstas no art. 45, o agente não possuía, ao tempo da ação ou da omissão, a plena capacidade de entender o caráter ilícito do fato ou de determinar-se de acordo com esse entendimento.', '["Redução de 1/3 a 2/3 da pena.","Capacidade apenas REDUZIDA (não plena) por dependência ou efeito de droga."]'::jsonb, '["Art. 45: isenção (incapacidade total). Art. 46: redução (capacidade parcial)."]'::jsonb, 'O dependente com capacidade parcialmente reduzida tem a pena diminuída.', '["Assertiva que isenta de pena o agente com capacidade apenas reduzida erra: a pena é reduzida."]'::jsonb, '[]'::jsonb, '["Art. 45"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-46'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na sentença condenatória, o juiz, com base em avaliação que ateste a necessidade de encaminhamento do agente para tratamento, realizada por profissional de saúde com competência específica na forma da lei, determinará que a tal se proceda, observado o disposto no art. 26 da Lei.', '["Sentença condenatória pode determinar o encaminhamento a tratamento.","Exige avaliação por profissional de saúde com competência específica.","Observa o art. 26."]'::jsonb, '["Depende de avaliação profissional que ateste a NECESSIDADE de tratamento."]'::jsonb, 'Condenado dependente, avaliado por profissional de saúde, é encaminhado ao tratamento na sentença.', '["Assertiva que dispensa a avaliação profissional para determinar o tratamento na sentença erra."]'::jsonb, '[]'::jsonb, '["Art. 26"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-47'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O procedimento dos processos por crimes da Lei rege-se pelo seu Capítulo, aplicando-se subsidiariamente o Código de Processo Penal e a Lei de Execução Penal. O agente das condutas do art. 28 (uso), salvo concurso com os crimes dos arts. 33 a 37, será processado e julgado na forma dos arts. 60 e seguintes da Lei dos Juizados Especiais. Na conduta do art. 28, não se imporá prisão em flagrante, devendo o autor ser imediatamente encaminhado ao juízo ou assumir o compromisso de comparecer, lavrando-se termo circunstanciado. Se ausente a autoridade judicial, as providências serão tomadas de imediato pela autoridade policial, no local, vedada a detenção do agente. Concluídos os procedimentos, o agente será submetido a exame de corpo de delito, se o requerer ou se a autoridade entender conveniente, e em seguida liberado.', '["Rito da própria lei; CPP e LEP subsidiários.","Art. 28: processado pelos Juizados Especiais (arts. 60 e seguintes da Lei 9.099).","Art. 28: sem prisão em flagrante; termo circunstanciado e liberação.","Vedada a detenção do usuário."]'::jsonb, '["Usuário NÃO é preso em flagrante.","Com concurso de tráfico, o rito é o da Lei de Drogas."]'::jsonb, 'O usuário flagrado com droga para consumo é encaminhado ao juizado, lavra-se termo circunstanciado e ele é liberado.', '["Assertiva que permite a prisão em flagrante do usuário do art. 28 erra: o autor é encaminhado ao juízo ou assume o compromisso de comparecer."]'::jsonb, '[{"termo":"Termo circunstanciado","significado":"Registro simplificado de infração de menor potencial ofensivo."}]'::jsonb, '["Art. 28","Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-48'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tratando-se de condutas tipificadas nos arts. 33, caput e §1º, e 34 a 37, o juiz, sempre que as circunstâncias o recomendem, empregará os instrumentos protetivos de colaboradores e testemunhas previstos na Lei nº 9.807, de 1999.', '["Nos crimes dos arts. 33, 34, 35, 36 e 37, o juiz emprega os instrumentos protetivos da Lei nº 9.807, de 1999.","Quando as circunstâncias recomendarem."]'::jsonb, '["Proteção a colaboradores e testemunhas."]'::jsonb, 'Testemunha ameaçada em processo de tráfico é incluída em programa de proteção.', '["Assertiva que torna obrigatória a proteção em todos os casos erra: depende das circunstâncias."]'::jsonb, '[]'::jsonb, '["Art. 41"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-49'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ocorrendo prisão em flagrante, a autoridade de polícia judiciária fará, imediatamente, comunicação ao juiz competente, remetendo-lhe cópia do auto, do qual será dada vista ao Ministério Público em 24 horas. Para a lavratura do auto e estabelecimento da materialidade, é suficiente o laudo de constatação da natureza e quantidade da droga, firmado por perito oficial ou, na falta deste, por pessoa idônea. O perito que subscrever o laudo preliminar não fica impedido de participar do laudo definitivo. Recebida a cópia do auto, o juiz, no prazo de 10 dias, certificará a regularidade formal do laudo de constatação e determinará a destruição das drogas apreendidas, guardando amostra para o laudo definitivo. A destruição será executada pelo delegado de polícia no prazo de 15 dias, na presença do Ministério Público e da autoridade sanitária.', '["Comunicação imediata ao juiz; vista ao MP em 24 horas.","Laudo de constatação (preliminar) basta para o flagrante e a materialidade.","Mesmo perito pode fazer o laudo definitivo.","Juiz, em 10 dias, certifica o laudo e determina a destruição, guardando amostra.","Destruição pelo delegado em 15 dias, com MP e autoridade sanitária."]'::jsonb, '["ATUALIZAÇÃO: §§ 3º e 4º incluídos pela Lei nº 12.961, de 2014 (destruição de drogas).","Prazos: 24 horas (vista ao MP), 10 dias (juiz) e 15 dias (destruição)."]'::jsonb, 'Com o laudo de constatação, o delegado lavra o flagrante, e a droga é destruída em 15 dias, guardada a amostra.', '["Assertiva que exige o laudo definitivo para a lavratura do flagrante erra: basta o laudo de constatação."]'::jsonb, '[{"termo":"Laudo de constatação","significado":"Laudo preliminar da natureza e quantidade da droga."}]'::jsonb, '["Art. 50-A","Art. 32"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-50'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A destruição das drogas apreendidas sem a ocorrência de prisão em flagrante será feita por incineração, no prazo máximo de 30 dias contados da data da apreensão, guardando-se amostra necessária à realização do laudo definitivo.', '["Drogas apreendidas sem flagrante: destruição por incineração.","Prazo máximo de 30 dias da apreensão.","Guarda de amostra para o laudo definitivo."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.840, de 2019.","Com flagrante, o prazo é de 15 dias (art. 50, §4º); sem flagrante, 30 dias."]'::jsonb, 'Droga apreendida em busca, sem prisão em flagrante, é incinerada em até 30 dias.', '["Assertiva que fixa em 15 dias a incineração das drogas apreendidas sem flagrante erra: são 30 dias."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-50-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O inquérito policial será concluído no prazo de 30 dias, se o indiciado estiver preso, e de 90 dias, quando solto. Os prazos podem ser duplicados pelo juiz, ouvido o Ministério Público, mediante pedido justificado da autoridade de polícia judiciária.', '["Preso: 30 dias.","Solto: 90 dias.","Prazos duplicáveis pelo juiz, ouvido o MP, a pedido justificado da polícia."]'::jsonb, '["Prazos próprios da Lei de Drogas, diferentes do CPP (10 e 30 dias).","Duplicação depende de pedido justificado."]'::jsonb, 'Indiciado preso por tráfico: inquérito em 30 dias, duplicáveis.', '["Assertiva que fixa em 10 dias o inquérito de preso por tráfico erra: a Lei de Drogas prevê 30 dias."]'::jsonb, '[]'::jsonb, '["Art. 52","Art. 10 do CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-51'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Findos os prazos do art. 51, a autoridade de polícia judiciária, remetendo os autos do inquérito ao juízo, relatará sumariamente as circunstâncias do fato, justificando as razões da classificação do delito, indicando a quantidade e natureza da substância, o local e as condições da ação, as circunstâncias da prisão, a conduta, a qualificação e os antecedentes do agente; ou requererá sua devolução para diligências necessárias. A remessa far-se-á sem prejuízo de diligências complementares necessárias ou úteis à elucidação do fato e à indicação dos bens, direitos e valores do agente, com resultado encaminhado ao juízo até 3 dias antes da audiência de instrução e julgamento.', '["Relatório sumário com circunstâncias, quantidade e natureza da droga, conduta e antecedentes.","Ou pedido de devolução para diligências.","Diligências complementares: resultado até 3 dias antes da audiência."]'::jsonb, '["Prazo de 3 dias antes da audiência para as diligências complementares."]'::jsonb, 'O delegado remete o inquérito com relatório sumário e continua diligenciando os bens do investigado.', '["Assertiva que impede diligências complementares após a remessa do inquérito erra."]'::jsonb, '[]'::jsonb, '["Art. 51"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-52'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer fase da persecução criminal relativa aos crimes previstos na Lei, são permitidos, além dos previstos em lei, mediante autorização judicial e ouvido o Ministério Público, a infiltração por agentes de polícia, em tarefas de investigação, constituída pelos órgãos especializados; e a não atuação policial sobre os portadores de drogas, seus precursores químicos ou outros produtos utilizados na produção, que se encontrem no território brasileiro, com a finalidade de identificar e responsabilizar maior número de integrantes do tráfico, sem prejuízo da ação penal cabível. Na não atuação policial (ação controlada), a autorização será concedida desde que sejam conhecidos o itinerário provável e a identificação dos agentes ou colaboradores.', '["Infiltração de agentes de polícia, com autorização judicial e oitiva do MP.","Ação controlada (não atuação policial) para identificar mais integrantes.","Exige itinerário provável e identificação dos agentes ou colaboradores."]'::jsonb, '["Autorização JUDICIAL e oitiva do MP em ambos os casos."]'::jsonb, 'A polícia acompanha o transporte da droga até o destino para prender toda a cadeia do tráfico.', '["Assertiva que dispensa autorização judicial para a infiltração policial no tráfico erra."]'::jsonb, '[{"termo":"Ação controlada","significado":"Retardamento da intervenção policial para obter melhor resultado investigativo."}]'::jsonb, '["Art. 33"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-53'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recebidos em juízo os autos do inquérito policial, de Comissão Parlamentar de Inquérito ou peças de informação, dar-se-á vista ao Ministério Público para, no prazo de 10 dias, requerer o arquivamento; requisitar as diligências que entender necessárias; ou oferecer denúncia, arrolar até 5 testemunhas e requerer as demais provas pertinentes.', '["Vista ao MP por 10 dias.","Opções: arquivar, requisitar diligências ou denunciar.","Denúncia: até 5 testemunhas."]'::jsonb, '["Prazo do MP: 10 dias.","Até 5 testemunhas (no ordinário do CPP, 8)."]'::jsonb, 'O MP oferece denúncia por tráfico, arrolando 5 testemunhas, em 10 dias.', '["Assertiva que fixa em 8 testemunhas o limite da denúncia na Lei de Drogas erra: são 5."]'::jsonb, '[]'::jsonb, '["Art. 55"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-54'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Oferecida a denúncia, o juiz ordenará a notificação do acusado para oferecer defesa prévia, por escrito, no prazo de 10 dias. Na resposta, consistente em defesa preliminar e exceções, o acusado poderá arguir preliminares e invocar todas as razões de defesa, oferecer documentos e justificações, especificar as provas e arrolar testemunhas, até o número de 5. As exceções serão processadas em apartado. Se a resposta não for apresentada no prazo, o juiz nomeará defensor para oferecê-la em 10 dias. Apresentada a defesa, o juiz decidirá em 5 dias. Se entender imprescindível, o juiz, no prazo máximo de 10 dias, determinará a apresentação do preso, a realização de diligências, exames e perícias.', '["Notificação do acusado para defesa prévia em 10 dias, ANTES do recebimento da denúncia.","Até 5 testemunhas.","Exceções em apartado.","Sem defesa: defensor nomeado, 10 dias.","Juiz decide em 5 dias."]'::jsonb, '["Defesa prévia ANTES do recebimento da denúncia (rito próprio da Lei de Drogas).","Prazos: 10, 5 e 10 dias."]'::jsonb, 'O acusado apresenta defesa prévia em 10 dias, e o juiz decide em 5 dias se recebe a denúncia.', '["Assertiva que manda citar o acusado após o recebimento da denúncia, na Lei de Drogas, sem defesa prévia, erra."]'::jsonb, '[]'::jsonb, '["Art. 56"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-55'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recebida a denúncia, o juiz designará dia e hora para a audiência de instrução e julgamento, ordenará a citação pessoal do acusado, a intimação do Ministério Público, do assistente, se for o caso, e requisitará os laudos periciais. Nas condutas dos arts. 33, caput e §1º, e 34 a 37, o juiz, ao receber a denúncia, poderá decretar o afastamento cautelar do denunciado de suas atividades, se for funcionário público, comunicando o órgão respectivo. A audiência será realizada dentro dos 30 dias seguintes ao recebimento da denúncia, salvo se determinada avaliação para atestar dependência de drogas, quando será realizada em 90 dias.', '["Recebimento da denúncia, audiência designada e citação pessoal.","Afastamento cautelar do funcionário público denunciado por tráfico.","Audiência em 30 dias; em 90 dias se houver avaliação de dependência."]'::jsonb, '["Prazos: 30 dias (regra) e 90 dias (avaliação de dependência)."]'::jsonb, 'O juiz recebe a denúncia contra um servidor por tráfico e o afasta cautelarmente.', '["Assertiva que fixa em 60 dias a audiência após o recebimento da denúncia, sem exceção, erra: são 30 dias (ou 90 com avaliação de dependência)."]'::jsonb, '[]'::jsonb, '["Art. 55"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-56'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na audiência de instrução e julgamento, após o interrogatório do acusado e a inquirição das testemunhas, será dada a palavra, sucessivamente, ao representante do Ministério Público e ao defensor do acusado, para sustentação oral, pelo prazo de 20 minutos para cada um, prorrogável por mais 10, a critério do juiz. Após proceder ao interrogatório, o juiz indagará das partes se restou algum fato para ser esclarecido, formulando as perguntas correspondentes se o entender pertinente e relevante.', '["Ordem prevista na lei: interrogatório e, depois, testemunhas.","Sustentação oral: 20 minutos para cada parte, prorrogáveis por 10.","Juiz pergunta se resta fato a esclarecer."]'::jsonb, '["Segundo o STF, o interrogatório deve ser o último ato, mesmo no rito da Lei de Drogas."]'::jsonb, 'MP e defesa fazem sustentação oral de 20 minutos cada, prorrogáveis por mais 10.', '["Assertiva que fixa em 15 minutos a sustentação oral na Lei de Drogas erra: são 20, prorrogáveis por 10."]'::jsonb, '[]'::jsonb, '["Art. 400 do CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-57'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Encerrados os debates, proferirá o juiz sentença de imediato, ou o fará em 10 dias, ordenando que os autos para isso lhe sejam conclusos. Os §§ 1º e 2º foram revogados.', '["Sentença de imediato ou em 10 dias."]'::jsonb, '["ATUALIZAÇÃO: §§ 1º e 2º revogados pela Lei nº 12.961, de 2014."]'::jsonb, 'Terminados os debates, o juiz sentencia na própria audiência ou em até 10 dias.', '["Assertiva que fixa em 30 dias o prazo da sentença na Lei de Drogas erra: são 10 dias."]'::jsonb, '[]'::jsonb, '["Art. 57"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-58'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes previstos nos arts. 33, caput e §1º, e 34 a 37, o réu não poderá apelar sem recolher-se à prisão, salvo se for primário e de bons antecedentes, assim reconhecido na sentença condenatória.', '["Réu não pode apelar sem se recolher à prisão.","Exceção: primário e de bons antecedentes, reconhecido na sentença."]'::jsonb, '["Dispositivo considerado incompatível com a presunção de inocência: prevalece o direito de recorrer em liberdade, salvo prisão cautelar fundamentada."]'::jsonb, 'Texto legal que exigia a prisão do réu para apelar, hoje de aplicação restrita pela jurisprudência.', '["Assertiva que aplica automaticamente a exigência de prisão para apelar no tráfico erra, à luz da presunção de inocência."]'::jsonb, '[]'::jsonb, '["Art. 44"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-59'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, a requerimento do Ministério Público ou do assistente de acusação, ou mediante representação da autoridade de polícia judiciária, poderá decretar, no curso do inquérito ou da ação penal, a apreensão e outras medidas assecuratórias nos casos em que haja suspeita de que os bens, direitos ou valores sejam produto do crime ou constituam proveito dos crimes da Lei, procedendo-se na forma dos arts. 125 e seguintes do Código de Processo Penal. Na hipótese do art. 366 do CPP, o juiz poderá determinar a prática de atos necessários à conservação dos bens. A ordem de apreensão ou sequestro poderá ser suspensa pelo juiz, ouvido o MP, quando a sua execução imediata puder comprometer as investigações.', '["Medidas assecuratórias sobre bens suspeitos de serem produto ou proveito do crime.","Decretadas pelo juiz, a pedido do MP ou do assistente ou por representação da polícia.","Procedimento dos arts. 125 e seguintes do CPP.","Suspensão da ordem se comprometer a investigação."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.840, de 2019.","§§ 1º e 2º revogados."]'::jsonb, 'O juiz decreta o sequestro de imóvel comprado com dinheiro do tráfico.', '["Assertiva que impede medidas assecuratórias antes da denúncia erra: podem ser decretadas no curso do inquérito."]'::jsonb, '[]'::jsonb, '["Art. 60-A","Art. 125 do CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-60'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se as medidas assecuratórias recaírem sobre moeda estrangeira, títulos, valores mobiliários ou cheques emitidos como ordem de pagamento, será determinada, imediatamente, a sua conversão em moeda nacional. A moeda estrangeira apreendida em espécie deve ser encaminhada a instituição financeira para alienação na forma prevista pelo Conselho Monetário Nacional. Se impossível a alienação, será custodiada pela instituição financeira até decisão sobre o seu destino. Caso verificada a inexistência de valor de mercado, seus espécimes poderão ser destruídos ou doados à representação diplomática do país de origem.', '["Moeda estrangeira, títulos, valores mobiliários e cheques: conversão imediata em moeda nacional.","Moeda em espécie: instituição financeira aliena conforme o CMN.","Sem alienação possível: custódia pela instituição.","Sem valor de mercado: destruição ou doação ao país de origem."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.886, de 2019."]'::jsonb, 'Dólares apreendidos em espécie são alienados por instituição financeira.', '["Assertiva que mantém a moeda estrangeira apreendida em espécie, sem conversão, erra."]'::jsonb, '[]'::jsonb, '["Art. 60"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-60-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A apreensão de veículos, embarcações, aeronaves e quaisquer outros meios de transporte e dos maquinários, utensílios, instrumentos e objetos de qualquer natureza utilizados para a prática, habitual ou não, dos crimes da Lei será imediatamente comunicada pela autoridade de polícia judiciária ao juízo competente. O juiz, no prazo de 30 dias contado da comunicação, determinará a alienação dos bens apreendidos, excetuadas as armas, que serão recolhidas na forma da legislação específica. A alienação será realizada em autos apartados. O juiz determinará a avaliação dos bens, por oficial de justiça no prazo de 5 dias da autuação, ou, se necessários conhecimentos especializados, por avaliador nomeado em prazo não superior a 10 dias.', '["Comunicação imediata da apreensão de meios de transporte e instrumentos ao juízo.","Alienação determinada pelo juiz em 30 dias, exceto armas.","Autos apartados.","Avaliação: oficial de justiça em 5 dias ou avaliador em até 10 dias."]'::jsonb, '["ATUALIZAÇÃO: caput com redação da Lei nº 14.322, de 2022; §§ 1º a 3º incluídos pela Lei nº 13.840, de 2019.","Prazos: 30, 5 e 10 dias."]'::jsonb, 'O carro usado no tráfico é apreendido, comunicado ao juiz e alienado em até 30 dias.', '["Assertiva que inclui as armas entre os bens alienados nesse procedimento erra: elas são recolhidas na forma da legislação específica."]'::jsonb, '[]'::jsonb, '["Art. 62"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-61'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comprovado o interesse público na utilização de quaisquer dos bens de que trata o art. 61, os órgãos de polícia judiciária, militar e rodoviária poderão deles fazer uso, sob sua responsabilidade e com o objetivo de sua conservação, mediante autorização judicial, ouvido o Ministério Público e garantida a prévia avaliação dos bens. O juízo deve cientificar o órgão gestor do Funad para que, em 10 dias, avalie a existência do interesse público e indique o órgão que deve receber o bem. Têm prioridade os órgãos de segurança pública que participaram das ações de investigação ou repressão ao crime. A autorização deverá conter a descrição do bem, a avaliação e o órgão responsável pelo uso, que enviará ao juiz informações periódicas sobre o estado de conservação.', '["Uso do bem apreendido por órgãos policiais, com autorização judicial e oitiva do MP.","Prévia avaliação do bem.","Funad avalia o interesse público em 10 dias.","Prioridade aos órgãos que participaram da investigação.","Informações periódicas sobre a conservação."]'::jsonb, '["ATUALIZAÇÃO: §§ 1º-A e 1º-B incluídos pela Lei nº 13.886, de 2019."]'::jsonb, 'A polícia que apreendeu a viatura usada no crime recebe autorização judicial para usá-la.', '["Assertiva que dispensa a autorização judicial para o uso do bem apreendido erra."]'::jsonb, '[]'::jsonb, '["Art. 61","Art. 63-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-62'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O depósito, em dinheiro, de valores referentes ao produto da alienação ou a numerários apreendidos ou que tenham sido convertidos deve ser efetuado na Caixa Econômica Federal, por meio de documento de arrecadação destinado a essa finalidade. Os depósitos devem ser transferidos pela Caixa para a conta única do Tesouro Nacional, independentemente de formalidade, no prazo de 24 horas, onde ficarão à disposição do Funad. Decretado o perdimento em favor da União, o valor do depósito será transformado em pagamento definitivo, respeitados os direitos de lesados e de terceiros de boa-fé. Os valores devolvidos por decisão judicial devem ser efetuados como anulação de receita do Funad. A Caixa deve manter o controle dos valores depositados ou devolvidos.', '["Depósitos em dinheiro na Caixa Econômica Federal.","Transferência à conta única do Tesouro em 24 horas, à disposição do Funad.","Perdimento: depósito vira pagamento definitivo.","Devolução: anulação de receita do Funad."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.886, de 2019; § 2º revogado pela Lei nº 14.973, de 2024.","Prazo de 24 horas."]'::jsonb, 'Dinheiro apreendido é depositado na Caixa e transferido ao Tesouro em 24 horas.', '["Assertiva que fixa o depósito em banco privado erra: é na Caixa Econômica Federal."]'::jsonb, '[]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-62-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao proferir a sentença, o juiz decidirá sobre o perdimento do produto, bem, direito ou valor apreendido ou objeto de medidas assecuratórias, e sobre o levantamento dos valores depositados em conta remunerada e a liberação dos bens utilizados nos termos do art. 62. Os bens, direitos ou valores apreendidos, após decretado o perdimento em favor da União, serão revertidos diretamente ao Funad. O juiz remeterá ao órgão gestor do Funad a relação dos bens perdidos. Transitada em julgado a sentença condenatória, o juiz, de ofício ou a requerimento do MP, remeterá à Senad a relação dos bens declarados perdidos em favor da União, entre outras providências.', '["Sentença decide o perdimento e o levantamento dos valores.","Bens perdidos revertem ao Funad.","Relação dos bens enviada ao Funad e, após o trânsito, à Senad."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.840, de 2019; § 3º revogado pela Lei nº 13.886, de 2019."]'::jsonb, 'Na sentença, o juiz decreta o perdimento de bens do tráfico em favor da União, que os reverte ao Funad.', '["Assertiva que destina os bens perdidos ao Tesouro estadual erra: revertem ao Funad."]'::jsonb, '[{"termo":"Senad","significado":"Secretaria Nacional de Políticas sobre Drogas."}]'::jsonb, '["Art. 62","Art. 63-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-63'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhum pedido de restituição será conhecido sem o comparecimento pessoal do acusado, podendo o juiz determinar a prática de atos necessários à conservação de bens, direitos ou valores.', '["Pedido de restituição exige comparecimento PESSOAL do acusado.","Juiz pode determinar atos de conservação dos bens."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.840, de 2019."]'::jsonb, 'O pedido de restituição do veículo só é conhecido se o acusado comparecer pessoalmente.', '["Assertiva que dispensa o comparecimento pessoal do acusado para o pedido de restituição erra."]'::jsonb, '[]'::jsonb, '["Art. 63-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-63-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz determinará a liberação total ou parcial dos bens, direitos e objetos de medidas assecuratórias quando comprovada a licitude de sua origem, mantendo-se a constrição dos bens, direitos e valores necessários e suficientes à reparação dos danos e ao pagamento de prestações pecuniárias, multas e custas decorrentes da infração penal.', '["Liberação total ou parcial dos bens com licitude comprovada.","Mantém-se a constrição necessária à reparação, prestações, multas e custas."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.840, de 2019."]'::jsonb, 'Comprovada a origem lícita de um imóvel, o juiz o libera, mantendo outros bens para cobrir multa e danos.', '["Assertiva que libera todos os bens, mesmo os necessários à reparação, após comprovada a licitude, erra."]'::jsonb, '[]'::jsonb, '["Art. 63-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-63-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete à Senad, do Ministério da Justiça e Segurança Pública, proceder à destinação dos bens apreendidos e não leiloados em caráter cautelar, cujo perdimento seja decretado em favor da União, por alienação (licitação, doação com encargo a entidades ou órgãos públicos e comunidades terapêuticas acolhedoras, ou venda direta), incorporação ao patrimônio de órgão da administração pública, destruição ou inutilização. A alienação por licitação é na modalidade leilão, para bens móveis e imóveis, independentemente do valor, assegurada a venda pelo maior lance, por preço não inferior a 50% do valor da avaliação, entre outras regras.', '["Senad destina os bens perdidos em favor da União.","Modalidades: alienação (licitação, doação com encargo, venda direta), incorporação, destruição ou inutilização.","Leilão: venda pelo maior lance, por preço não inferior a 50% da avaliação."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.886, de 2019.","Piso do leilão: 50% da avaliação."]'::jsonb, 'A Senad leiloa o imóvel perdido, por no mínimo 50% do valor da avaliação.', '["Assertiva que fixa o piso do leilão em três quartos da avaliação erra: é 50%."]'::jsonb, '[]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-63-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Compete ao Ministério da Justiça e Segurança Pública regulamentar os procedimentos relativos à administração, à preservação e à destinação dos recursos provenientes de delitos e atos ilícitos e estabelecer os valores abaixo dos quais se deve proceder à sua destruição ou inutilização.', '["O Ministério da Justiça regulamenta a administração, a preservação e a destinação dos recursos.","Define os valores abaixo dos quais se destrói ou inutiliza."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.886, de 2019."]'::jsonb, 'Portaria do Ministério fixa o valor mínimo para a alienação de bens apreendidos.', '["Assertiva que atribui ao Poder Judiciário a regulamentação desses procedimentos erra."]'::jsonb, '[]'::jsonb, '["Art. 63-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-63-d'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O produto da alienação dos bens apreendidos ou confiscados será revertido integralmente ao Funad, nos termos do parágrafo único do art. 243 da Constituição, vedada a sub-rogação sobre o valor da arrematação para saldar eventuais multas, encargos ou tributos pendentes. O disposto não prejudica o ajuizamento de execução fiscal em relação aos antigos devedores.', '["Produto da alienação revertido integralmente ao Funad.","Vedada a sub-rogação do valor da arrematação para pagar multas, encargos ou tributos.","Execução fiscal contra antigos devedores permanece possível."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.886, de 2019."]'::jsonb, 'O arrematante não responde por tributos antigos do bem, que são cobrados do antigo devedor.', '["Assertiva que permite pagar débitos do bem com o valor da arrematação erra: é vedada a sub-rogação."]'::jsonb, '[]'::jsonb, '["Art. 63-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-63-e'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na hipótese de condenação por infrações às quais a Lei comine pena máxima superior a 6 anos de reclusão, poderá ser decretada a perda, como produto ou proveito do crime, dos bens correspondentes à diferença entre o valor do patrimônio do condenado e aquele compatível com o seu rendimento lícito. A decretação fica condicionada à existência de elementos probatórios que indiquem conduta criminosa habitual, reiterada ou profissional do condenado ou sua vinculação a organização criminosa. Patrimônio do condenado são todos os bens de sua titularidade, ou sobre os quais tenha domínio e benefício direto ou indireto, na data da infração ou recebidos posteriormente, e os transferidos a terceiros a título gratuito ou mediante contraprestação irrisória a partir do início da atividade criminal. O condenado poderá demonstrar a inexistência da incompatibilidade ou a procedência lícita do patrimônio.', '["Perda alargada: diferença entre o patrimônio e o rendimento lícito.","Pena máxima superior a 6 anos de reclusão.","Exige indícios de conduta habitual, reiterada ou profissional, ou vínculo com organização criminosa.","Patrimônio inclui bens transferidos a terceiros de forma gratuita ou irrisória.","O condenado pode comprovar a origem lícita."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.886, de 2019.","Há inversão do ônus de demonstrar a origem lícita."]'::jsonb, 'O condenado por tráfico organizado perde bens incompatíveis com sua renda lícita.', '["Assertiva que aplica a perda alargada a qualquer pena, mesmo inferior a 6 anos, erra."]'::jsonb, '[{"termo":"Perda alargada","significado":"Perda de bens incompatíveis com o rendimento lícito do condenado."}]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-63-f'
