insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União, por intermédio da Senad, poderá firmar convênio com os Estados, com o Distrito Federal e com organismos orientados para a prevenção do uso indevido de drogas, a atenção e a reinserção social de usuários ou dependentes e a atuação na repressão à produção não autorizada e ao tráfico ilícito, com vistas à liberação de equipamentos e de recursos por ela arrecadados, para a implantação e execução de programas relacionados às drogas.', '["A União, pela Senad, pode firmar convênios com Estados, DF e organismos.","Objetivo: liberar equipamentos e recursos arrecadados para programas."]'::jsonb, '["Faculdade (''poderá'')."]'::jsonb, 'A Senad celebra convênio com um Estado para equipar a polícia, com recursos arrecadados.', '["Assertiva que torna obrigatório o convênio da União com os Estados erra."]'::jsonb, '[]'::jsonb, '["Art. 73"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-64'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'De conformidade com os princípios da não intervenção em assuntos internos, da igualdade jurídica e do respeito à integridade territorial dos Estados, e observado o espírito das Convenções das Nações Unidas, o governo brasileiro prestará, quando solicitado, cooperação a outros países e organismos internacionais e, quando necessário, deles solicitará a colaboração, nas áreas de intercâmbio de informações sobre legislações, experiências, projetos e programas de prevenção e atenção; intercâmbio de inteligência policial sobre produção e tráfico de drogas e delitos conexos, em especial o tráfico de armas, a lavagem de dinheiro e o desvio de precursores químicos; e intercâmbio de informações policiais e judiciais sobre produtores e traficantes.', '["Cooperação internacional baseada na não intervenção, igualdade jurídica e integridade territorial.","Intercâmbio de informações sobre legislação e programas.","Intercâmbio de inteligência policial (tráfico de armas, lavagem, precursores).","Intercâmbio de informações policiais e judiciais sobre traficantes."]'::jsonb, '["Cooperação respeita os princípios do Direito Internacional."]'::jsonb, 'A Polícia Federal troca informações de inteligência com polícias estrangeiras sobre uma rota do tráfico.', '["Assertiva que dispensa o respeito à não intervenção em assuntos internos na cooperação internacional erra."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-65'
