insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A liberação dos recursos previstos na Lei nº 7.560, de 1986, em favor de Estados e do Distrito Federal, dependerá de sua adesão e respeito às diretrizes básicas contidas nos convênios firmados e do fornecimento de dados necessários à atualização do sistema do art. 17, pelas respectivas polícias judiciárias.', '["Liberação de recursos aos Estados e ao DF depende de adesão e respeito às diretrizes dos convênios.","Exige fornecimento de dados ao sistema do art. 17."]'::jsonb, '["Condição: dados fornecidos pelas polícias judiciárias."]'::jsonb, 'O Estado que não fornece dados das apreensões pode não receber os recursos.', '["Assertiva que libera os recursos sem exigir dados das polícias judiciárias erra."]'::jsonb, '[]'::jsonb, '["Art. 17"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-67'
