insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os gestores e entidades que recebam recursos públicos para execução das políticas sobre drogas deverão garantir o acesso às suas instalações, à documentação e a todos os elementos necessários à efetiva fiscalização pelos órgãos competentes.', '["Gestores e entidades que recebem recursos garantem acesso à fiscalização.","Abrange instalações, documentação e demais elementos."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 13.840, de 2019."]'::jsonb, 'A comunidade terapêutica financiada deve permitir a inspeção das instalações e dos documentos.', '["Assertiva que dispensa a fiscalização das entidades privadas que recebem recursos erra."]'::jsonb, '[]'::jsonb, '["Art. 67"]'::jsonb, 'under_review', 'claude'
