insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União, os Estados, o Distrito Federal e os Municípios poderão criar estímulos fiscais e outros, destinados às pessoas físicas e jurídicas que colaborem na prevenção do uso indevido de drogas, atenção e reinserção social de usuários e dependentes e na repressão da produção não autorizada e do tráfico ilícito.', '["Todos os entes podem criar estímulos fiscais e outros.","Para quem colabora na prevenção, atenção, reinserção e repressão."]'::jsonb, '["Faculdade dos entes federados."]'::jsonb, 'Município concede incentivo fiscal à empresa que contrata usuários em reinserção.', '["Assertiva que torna obrigatória a criação de estímulos fiscais erra: é faculdade."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
