on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de falência ou liquidação extrajudicial de empresas ou estabelecimentos hospitalares, de pesquisa, de ensino ou congêneres, assim como nos serviços de saúde que produzirem, venderem, adquirirem, consumirem, prescreverem ou fornecerem drogas, incumbe ao juízo determinar, imediatamente à ciência, que sejam lacradas as instalações; ordenar à autoridade sanitária a adoção das medidas para o recebimento e guarda das drogas arrecadadas; e dar ciência ao Ministério Público. Da licitação para alienação de substâncias não proscritas só podem participar pessoas jurídicas habilitadas na área de saúde ou pesquisa científica que comprovem a destinação lícita. O produto não arrematado será destruído pela autoridade sanitária, na presença dos Conselhos Estaduais sobre Drogas e do MP, ressalvada a hipótese do §3º.', '["Falência ou liquidação de estabelecimentos que manipulam drogas.","Juízo lacra as instalações e ordena a guarda das drogas pela autoridade sanitária.","Ciência ao MP.","Licitação só para pessoas jurídicas habilitadas na saúde ou pesquisa.","Produto não arrematado é destruído pela autoridade sanitária."]'::jsonb, '["Hipótese específica de falência de estabelecimentos de saúde, pesquisa ou ensino."]'::jsonb, 'Hospital em liquidação extrajudicial tem as instalações lacradas e as drogas recolhidas pela autoridade sanitária.', '["Assertiva que dispensa a ciência ao Ministério Público na falência desses estabelecimentos erra."]'::jsonb, '[]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-69'
