on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Encerrado o processo criminal ou arquivado o inquérito policial, o juiz, de ofício, mediante representação da autoridade de polícia judiciária, ou a requerimento do Ministério Público, determinará a destruição das amostras guardadas para contraprova, certificando nos autos.', '["Fim do processo ou arquivamento do inquérito: destruição das amostras de contraprova.","De ofício, por representação da polícia ou a pedido do MP."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 13.840, de 2019."]'::jsonb, 'Arquivado o inquérito, o juiz manda destruir as amostras guardadas.', '["Assertiva que mantém as amostras indefinidamente após o fim do processo erra."]'::jsonb, '[]'::jsonb, '["Art. 50"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-72'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União poderá estabelecer convênios com os Estados e com o Distrito Federal, visando à prevenção e repressão do tráfico ilícito e do uso indevido de drogas, e com os Municípios, com o objetivo de prevenir o uso indevido e de possibilitar a atenção e reinserção social de usuários e dependentes.', '["Convênios com Estados e DF: prevenção e repressão.","Convênios com Municípios: prevenção, atenção e reinserção."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 12.219, de 2010.","Com os Municípios, o foco é prevenção e atenção (e não a repressão)."]'::jsonb, 'A União firma convênio com um Município para ações de prevenção.', '["Assertiva que prevê convênio com Municípios para repressão ao tráfico erra: o foco é prevenção, atenção e reinserção."]'::jsonb, '[]'::jsonb, '["Art. 64"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'drogas' and u.unit_key = 'art-73'
